-- Sociology 19 Dec 2023 Shift 2 (English and Hindi). Approved 20 Oct 2026.
-- Taken from NTA's question paper (2023-12-19-Evening-QP.pdf):
-- 1. Q1-5: the Data Interpretation table was missing. The real table (5 colleges, employees, M:F ratio) is added to layout_text.
--    Checked against the stored answers: total males 8360 (Q1), average females 1312 (Q2), about 13% (Q3), 780:497 (Q4), about 6% (Q5).
-- 2. Q46-50: Q46 held only a two-line summary in brackets and Q47-50 had no passage. The full passage is added to layout_text
--    for all five, and the bracketed summary is removed from Q46. Passage text was machine-read from NTA's page.
-- Questions, options and answers unchanged.
begin;

update public.questions set layout_text = $t$<p>The following table shows the number of employees working in five different colleges A-E, alongwith the ratio of Males to Females [M : F] among them. Based on the data in the table, answer the questions that follow.</p><p><b>College-wise Details of Employees</b></p><table border="1" width="100%" cellpadding="6"><tr><th>College</th><th>Number of Employees</th><th>Ratio<br>M : F</th></tr><tr><td>A</td><td>3040</td><td>13 : 6</td></tr><tr><td>B</td><td>3360</td><td>4 : 3</td></tr><tr><td>C</td><td>2920</td><td>9 : 11</td></tr><tr><td>D</td><td>2760</td><td>10 : 13</td></tr><tr><td>E</td><td>2840</td><td>13 : 7</td></tr></table>$t$
where paper_id = '05_SOCIOLOGY_19_DEC_2023_SHIFT2' and question_number between 1 and 5 and coalesce(layout_text, '') = '';
update public.questions_hindi set layout_text = $t$<p>निम्नांकित तालिका में पाँच अलग-अलग महाविद्यालय A से E में कार्यरत कर्मचारियों की संख्या को पुरुष और महिला अनुपात (पुरुषः महिला) सहित दर्शाया गया है। तालिका में डाटा के आधार पर नीचे दिये गये प्रश्नों के उत्तर दीजिये।</p><p><b>कर्मचारियों का महाविद्यालय-वार ब्यौरा</b></p><table border="1" width="100%" cellpadding="6"><tr><th>महाविद्यालय</th><th>कर्मचारियों की संख्या</th><th>अनुपात<br>पुरुष : महिला</th></tr><tr><td>A</td><td>3040</td><td>13 : 6</td></tr><tr><td>B</td><td>3360</td><td>4 : 3</td></tr><tr><td>C</td><td>2920</td><td>9 : 11</td></tr><tr><td>D</td><td>2760</td><td>10 : 13</td></tr><tr><td>E</td><td>2840</td><td>13 : 7</td></tr></table>$t$
where paper_id = '05_SOCIOLOGY_19_DEC_2023_SHIFT2' and question_number between 1 and 5 and coalesce(layout_text, '') = '';

update public.questions set layout_text = $p$<p>Read the passage and answer the questions that follow :</p><p>Science and the techniques to which it has given rise have changed human life during the last hundred and fifty years more than it had been changed since men took to agriculture, and the changes that are being wrought by science continue at an increasing speed. There is no sign of any new stability to be attained on some scientific plateau. On the contrary, there is every reason to think that the revolutionary possibilities of science extend immeasurably beyond what has so far been realised. Can the human race adjust itself quickly enough to these vertiginous transformations, or will it, as innumerable former species have done, perish from lack of adaptability? The dinosaurs were, in their day, the lords of creation, and if there had been philosophers among them, not one would have foreseen that the whole race might perish. But they became extinct because they could not adapt themselves to a world without swamps. In the case of man and science there is a wholly new factor, namely that man himself is creating the changes of environment to which he will have to adjust himself with unprecedented rapidity. But, although man through his scientific skill is the cause of the changes of environment, most of these changes are not willed by human beings. Although they come about through human agencies, they have, or at any rate have had so far, something of the inexorable inevitability of natural forces. Whether Nature dried up the swamps or men deliberately drained them, makes little difference as regards the ultimate result. Whether men will be able to survive the changes of environment that their own skill has brought about is an open question. If the answer is in the affirmative, it will be known some day; if not, not. If the answer is to be in the affirmative, men will have to apply scientific ways of thinking to themselves and their institutions.</p>$p$
where paper_id = '05_SOCIOLOGY_19_DEC_2023_SHIFT2' and question_number between 46 and 50 and coalesce(layout_text, '') = '';
update public.questions_hindi set layout_text = $p$<p>दिए गए गद्यांश को पढ़िए और प्रश्नों के उत्तर दीजिए।</p><p>पिछले डेढ़ सौ वर्षों के दौरान विज्ञान और उससे जनित तकनीकों ने मानव द्वारा कृषि कार्य अपनाए जाने के बाद मानव जीवन में हुए परिवर्तनों से अधिक परिवर्तन किया है, और विज्ञान द्वारा परविर्तन सतत रूप से त्वरित गति से हो रहा है। कुछ वैज्ञानिक अधित्यका पर किसी नये स्थायित्व का कोई संकेत नहीं है। इसके विपरीत, यह विचार करने का हर कारण है कि अब तक जो प्राप्त हुआ हैं, उसके परे विज्ञान की क्रान्तिकारी संभावनायें अमापनीय रूप से विस्तारित हैं। क्या मानव जाति इन प्ररिभ्रामी रूपांतरण के साथ शीघ्रतापूर्वक पर्याप्त रूप से समायोजन कर सकती है, या जैसा कि असंख्य पूर्व प्रजातियों (स्पीशीज) ने किया है, वैसा ही अनुकूलनीयता के अभाव में यह मानव जाति भी समाप्त हो जाएगी। अपने काल में डायनोसोर सृष्टि निर्माता थे, और यदि उनके बीच दार्शनिक रहे होते तो किसी ने भी यह पूर्वानुमान नहीं किया होता कि संपूर्ण प्रजाति विनष्ट हो सकती है। परंतु वे विलुप्त हो गए क्योंकि वे दलदल रहित दुनिया ( भूमंडल) से अपने को अनुकुलित नहीं कर सके। मानव और विज्ञान के मामलों में, पूर्णतया एक नवीन कारक है, जैसे कि मानव स्वयं पर्यावरण परिवर्तन कर रहा है जिसमें उसे अभूतपूर्ण तीव्रता के साथ स्वयं को समायोजित करना होगा। परंतु यद्यपि मानव अपने वैज्ञानिक कौशल द्वारा पर्यावरण में परिवर्तन का कारण है, इन परिवर्तनों में अधिकांश परिवर्तन मानव प्राणी के इच्छा के अनुरूप नहीं होते हैं। यद्यपि ये परिवर्तन मानव अभिकरणों द्वारा किए जाते हैं, जो अभी तक प्राकृतिक बलों की अनमनीय अनिवार्यता की कोई चीज़ मानी जाती थी। चाहे प्रकृति दलदल को शुष्क बनाए या मानव सप्रयास जल निकास करे, उसके अंतिम परिणाम में कोई अंतर नहीं होता है। क्या मानव अपने कौशल द्वारा लाये गये पर्यावरण परिवर्तन के बीच जीवित रहने में समर्थ होगा, यह प्रश्न अभी भी बना हुआ है। यदि इसका उत्तर सकारात्मक है किसी दिन इसका पता चलेगा यदि नहीं तो नहीं। यदि उत्तर सकारात्मक होने वाला है; मानव को स्वयं और उनकी संस्थाओं के प्रति चिंतन के वैज्ञानिक तरीके का प्रयोग करना होगा।</p>$p$
where paper_id = '05_SOCIOLOGY_19_DEC_2023_SHIFT2' and question_number between 46 and 50 and coalesce(layout_text, '') = '';

-- remove the bracketed summary from Q46 (keeps only the question after it)
update public.questions set question_text = regexp_replace(question_text, '^\[Comprehension passage:[^\]]*\]\s*(<br>)?', '')
where paper_id = '05_SOCIOLOGY_19_DEC_2023_SHIFT2' and question_number = 46 and question_text like '[Comprehension passage:%';
update public.questions_hindi set question_text = regexp_replace(question_text, '^\[गद्यांश:[^\]]*\]\s*(<br>)?', '')
where paper_id = '05_SOCIOLOGY_19_DEC_2023_SHIFT2' and question_number = 46 and question_text like '[गद्यांश:%';

commit;

-- VERIFY: expect 20 rows. Q1-5 has_table = true, Q46-50 has_passage = true, and Q46 starts with the question itself.
select 'EN' as lang, question_number, layout_text like '%<table%' as has_table, length(layout_text) > 1500 as has_passage, left(question_text, 60) as question_start
from public.questions where paper_id = '05_SOCIOLOGY_19_DEC_2023_SHIFT2' and (question_number <= 5 or question_number >= 46)
union all
select 'HI', question_number, layout_text like '%<table%', length(layout_text) > 1500, left(question_text, 60)
from public.questions_hindi where paper_id = '05_SOCIOLOGY_19_DEC_2023_SHIFT2' and (question_number <= 5 or question_number >= 46)
order by 2, 1;
